/**
 * Maps a provider/app string from the backend ("Claude Code", "claude_code", "gdrive") to a
 * registry id, or null when there is no mark (the caller then gets the letter fallback).
 */
function resolveProviderMarkIdUnchecked(value) {
  const key = String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/[\s_.]+/g, "-");
  if (!key) return null;
  if (Object.prototype.hasOwnProperty.call(MARKS, key)) return key;
  if (Object.prototype.hasOwnProperty.call(ALIASES, key)) return ALIASES[key];
  return null;
}

checkProviderRegistry(PROVIDER_MARKS, providerMarkIds);
export function resolveProviderMarkId(value) { return checkProviderResolution(value, resolveProviderMarkIdUnchecked(value), MARKS, ALIASES); }
